{
 "name": "ah",
 "displayName": "Agent Hierarchy — Role/Model Assignment",
 "version": "0.133.1",
 "description": "Multi-agent role hierarchy, each on the right model. Optional herdr transport for pane-based teams.",
 "author": {
  "name": "Jim Cline"
 },
 "license": "Apache-2.0",
 "keywords": [
  "subagent",
  "delegation",
  "orchestration",
  "models",
  "review",
  "cost",
  "herdr"
 ],
 "hooks": "./mod/hooks.json",
 "types": "./mod/types/index.d.ts",
 "userConfig": {
  "status_entry": {
   "type": "boolean",
   "title": "Status entry",
   "description": "Show the hierarchy line (⚠ ah: …) in the status area. Off by default; turn it on if claude-tui-line's ah item does not already show it.",
   "default": false
  },
  "toast_seconds": {
   "type": "number",
   "title": "Toast seconds",
   "description": "How long hierarchy notices stay on screen, in seconds (2-60); 0 turns them off. Click a notice to dismiss it early.",
   "default": 10
  }
 }
}

